+    auto SE = SymbolicSize{"embeds_stride"};
+    auto SP = SymbolicSize{"previous_hidden_stride"};
+    auto SO = SymbolicSize{"output_stride"};
+    auto device_ = SymbolicDevice{};
+    H.set_value(kHidden);
+    H2.set_value(kHidden * 2);
+    device_.set_options<kDLCUDA>();
